const prev = $input.first().json;
const map = JSON.parse($env.N8N_AGENT_MAP || '{}');
const entry = map[prev.reviewerLogin];
if (!entry || entry.role !== 'reviewer') {
  throw new Error(`N8N_AGENT_MAP has no reviewer entry for login "${prev.reviewerLogin}"`);
}
return [{ json: { ...prev, host: entry.host, sshPort: entry.port, sshUser: entry.user } }];

const j = $input.first().json;
const prompt = `You are reviewing PR #${j.prNumber}: ${j.prTitle}

PR description:
${j.prBody}

Produce a concise code review. Focus on:
- correctness bugs in the diff
- test coverage gaps
- API / backward-compat regressions
- obvious security issues

Output format: plain markdown. Start with a one-line verdict
(APPROVE / REQUEST_CHANGES / COMMENT). Then bullet findings with
file:line references. If nothing substantive, say so in one line.
The diff is appended below after === DIFF ===.
`;
return [{ json: { ...j, promptB64: Buffer.from(prompt, 'utf8').toString('base64') } }];
